#ifndef RENDER_ASSETS_H
#define RENDER_ASSETS_H
#include <android/asset_manager.h>
#include <android/log.h>
#include <GLES/gl.h>
#include <vector>
#include <string>
#include <cstring>
#include <cstdint>
struct Color{float r,g,b,a;Color(float R=1,float G=1,float B=1,float A=1):r(R),g(G),b(B),a(A){}};
struct GPUVertex{GLfloat x,y,z,nx,ny,nz,u,v;};
struct Mesh{struct Part{GLuint vbo;int material,count;};std::vector<Part>parts;
 void clear(){for(size_t i=0;i<parts.size();i++)if(parts[i].vbo)glDeleteBuffers(1,&parts[i].vbo);parts.clear();}
 bool load(AAssetManager*m,const char*path){clear();AAsset*a=AAssetManager_open(m,path,AASSET_MODE_BUFFER);if(!a)return false;const unsigned char*s=(const unsigned char*)AAsset_getBuffer(a);size_t size=(size_t)AAsset_getLength(a);if(!s||size<8||std::memcmp(s,"ARM1",4)){AAsset_close(a);return false;}uint32_t n;std::memcpy(&n,s+4,4);size_t p=8;bool ok=n>0&&n<=32;for(uint32_t i=0;ok&&i<n;i++){uint32_t mat,count;if(p+8>size){ok=false;break;}std::memcpy(&mat,s+p,4);std::memcpy(&count,s+p+4,4);p+=8;if(mat>16||!count||count%3||count>1000000||(size_t)count*sizeof(GPUVertex)>size-p){ok=false;break;}Part q;q.material=int(mat);q.count=int(count);glGenBuffers(1,&q.vbo);glBindBuffer(GL_ARRAY_BUFFER,q.vbo);glBufferData(GL_ARRAY_BUFFER,(size_t)count*sizeof(GPUVertex),s+p,GL_STATIC_DRAW);parts.push_back(q);p+=(size_t)count*sizeof(GPUVertex);}AAsset_close(a);glBindBuffer(GL_ARRAY_BUFFER,0);if(!ok)clear();return ok;}
};
struct AssetLibrary{GLuint textures[17];Mesh scene,fixture,sphere,body[3],head[3],thigh,calf,foot,upperarm,forearm,hand,weapons[10];int baseLoaded,sceneLevel;
 AssetLibrary():baseLoaded(0),sceneLevel(-1){for(int i=0;i<17;i++)textures[i]=0;}
 GLuint tga(AAssetManager*m,const char*path){AAsset*a=AAssetManager_open(m,path,AASSET_MODE_BUFFER);if(!a)return 0;const unsigned char*s=(const unsigned char*)AAsset_getBuffer(a);size_t size=(size_t)AAsset_getLength(a);if(!s||size<18){AAsset_close(a);return 0;}int w=s[12]|s[13]<<8,h=s[14]|s[15]<<8,ch=s[16]/8;size_t p=18+s[0];if(s[1]||s[2]!=2||w<1||h<1||w>2048||h>2048||(ch!=3&&ch!=4)||p>size||(size_t)w*h*ch>size-p){AAsset_close(a);return 0;}std::vector<unsigned char>pix((size_t)w*h*4);for(int y=0;y<h;y++)for(int x=0;x<w;x++){int sy=(s[17]&32)?h-1-y:y,sx=(s[17]&16)?w-1-x:x;size_t q=p+((size_t)sy*w+sx)*ch,k=((size_t)y*w+x)*4;pix[k]=s[q+2];pix[k+1]=s[q+1];pix[k+2]=s[q];pix[k+3]=ch==4?s[q+3]:255;}AAsset_close(a);GLuint id;glGenTextures(1,&id);glBindTexture(GL_TEXTURE_2D,id);glPixelStorei(GL_UNPACK_ALIGNMENT,1);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,&pix[0]);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);return id;}
 void tex(int i){if(i>=0&&i<17&&textures[i]){glEnable(GL_TEXTURE_2D);glBindTexture(GL_TEXTURE_2D,textures[i]);glTexEnvf(GL_TEXTURE_ENV,GL_TEXTURE_ENV_MODE,GL_MODULATE);}else glDisable(GL_TEXTURE_2D);}
 static void response(int mat){float strength=0,shine=8;switch(mat){case 0:strength=.78f;shine=64;break;case 1:strength=.18f;shine=28;break;case 2:strength=.13f;shine=20;break;case 4:strength=.10f;shine=12;break;case 9:strength=.12f;shine=16;break;case 10:strength=.14f;shine=16;break;case 11:strength=.25f;shine=32;break;case 12:strength=.18f;shine=18;break;case 5:case 13:strength=.025f;shine=10;break;case 15:strength=.08f;shine=18;break;case 16:strength=.08f;shine=12;break;default:break;}GLfloat spec[]={strength,strength,strength,1};glMaterialfv(GL_FRONT_AND_BACK,GL_SPECULAR,spec);glMaterialf(GL_FRONT_AND_BACK,GL_SHININESS,shine);}
 void draw(const Mesh&m,int over=-1,Color color=Color()){glEnableClientState(GL_VERTEX_ARRAY);glEnableClientState(GL_NORMAL_ARRAY);glEnableClientState(GL_TEXTURE_COORD_ARRAY);glDisableClientState(GL_COLOR_ARRAY);GLfloat c[]={color.r,color.g,color.b,color.a},sp[]={.85f,.85f,.85f,1};glMaterialfv(GL_FRONT_AND_BACK,GL_AMBIENT_AND_DIFFUSE,c);glLightfv(GL_LIGHT0,GL_SPECULAR,sp);glColor4f(color.r,color.g,color.b,color.a);for(size_t i=0;i<m.parts.size();i++){const Mesh::Part&p=m.parts[i];int mat=over==-1?p.material:over;response(mat);if(mat==9){glEnable(GL_BLEND);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);glDepthMask(GL_FALSE);}tex(mat);glBindBuffer(GL_ARRAY_BUFFER,p.vbo);glVertexPointer(3,GL_FLOAT,sizeof(GPUVertex),(void*)0);glNormalPointer(GL_FLOAT,sizeof(GPUVertex),(void*)(3*sizeof(float)));glTexCoordPointer(2,GL_FLOAT,sizeof(GPUVertex),(void*)(6*sizeof(float)));glDrawArrays(GL_TRIANGLES,0,p.count);if(mat==9){glDepthMask(GL_TRUE);glDisable(GL_BLEND);}}}
 void orb(float x,float y,float z,float sx,float sy,float sz,Color c){glPushMatrix();glTranslatef(x,y,z);glScalef(sx,sy,sz);draw(sphere,-2,c);glPopMatrix();}
 void list(std::vector<Mesh*>&v){v.push_back(&scene);v.push_back(&fixture);v.push_back(&sphere);for(int i=0;i<3;i++){v.push_back(&body[i]);v.push_back(&head[i]);}v.push_back(&thigh);v.push_back(&calf);v.push_back(&foot);v.push_back(&upperarm);v.push_back(&forearm);v.push_back(&hand);for(int i=0;i<10;i++)v.push_back(&weapons[i]);}
 void clear(bool del){std::vector<Mesh*>v;list(v);for(size_t i=0;i<v.size();i++){if(del)v[i]->clear();else v[i]->parts.clear();}for(int i=0;i<17;i++){if(del&&textures[i])glDeleteTextures(1,&textures[i]);textures[i]=0;}baseLoaded=0;sceneLevel=-1;}
 bool model(Mesh&m,AAssetManager*a,const char*name){std::string p="models/";p+=name;p+=".mesh";bool ok=m.load(a,p.c_str());if(!ok)__android_log_print(ANDROID_LOG_ERROR,"BotArena","Falha recurso %s",p.c_str());return ok;}
 void loadScene(AAssetManager*m,int level){if(sceneLevel==level&&!scene.parts.empty())return;char p[64];::snprintf(p,sizeof(p),"models/level_%d.mesh",level);if(!scene.load(m,p))__android_log_print(ANDROID_LOG_ERROR,"BotArena","Falha recurso %s",p);sceneLevel=level;}
 void load(AAssetManager*m,int level){clear(true);const char*names[]={"metal","polymer","wood","wall","floor","skin","bone","cloth","fog","blood","mold","tiles","rust","human_skin","human_cloth","human_mask","hair"};for(int i=0;i<17;i++){if(i==8)continue;std::string p="textures/";p+=names[i];p+=".tga";textures[i]=tga(m,p.c_str());if(textures[i])baseLoaded++;else __android_log_print(ANDROID_LOG_ERROR,"BotArena","Falha recurso %s",p.c_str());}if(model(fixture,m,"fixture"))baseLoaded++;if(model(sphere,m,"sphere"))baseLoaded++;for(int i=0;i<3;i++){char n[32];::snprintf(n,sizeof(n),"body_%d",i);if(model(body[i],m,n))baseLoaded++;::snprintf(n,sizeof(n),"head_%d",i);if(model(head[i],m,n))baseLoaded++;}Mesh*limbs[]={&thigh,&calf,&foot,&upperarm,&forearm,&hand};const char*ln[]={"thigh","calf","foot","upperarm","forearm","hand"};for(int i=0;i<6;i++)if(model(*limbs[i],m,ln[i]))baseLoaded++;for(int i=0;i<10;i++){char n[32];::snprintf(n,sizeof(n),"weapon_%d",i);if(model(weapons[i],m,n))baseLoaded++;}loadScene(m,level);}
 int loaded()const{return baseLoaded+(!scene.parts.empty()?1:0);}
};
#endif
